CREATE TABLE IF NOT EXISTS `reactions` (`id` INT AUTO_INCREMENT PRIMARY KEY, `target_type` VARCHAR(16) NOT NULL DEFAULT 'profile', `target_id` INT NOT NULL, `user_id` INT NOT NULL, `emoji` VARCHAR(16) NOT NULL, `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT `uq_reaction` UNIQUE (`user_id`, `target_type`, `target_id`, `emoji`), CONSTRAINT `fk_reactions_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_reactions_target ON `reactions` (`target_type`, `target_id`);
